#[tokio::test]
async fn send_fills_defaults_and_redacts() {
    let exp = MemoryLogExporter::new();
    let c = client(&exp);
    assert!(format!("{c:?}").contains("svc"));
    let ts = UNIX_EPOCH + Duration::from_secs(10);
    c.send(LogEntry::Input(
        LogInput::new("hi")
            .attribute("password", "p")
            .timestamp(ts)
            .trace("4bf92f3577b34da6a3ce929d0e0e4736", "00f067aa0ba902b7"),
    ));
    let mut record = LogRecord::new(Severity::Warn, "raw");
    record.resource.insert("service.name".into(), "own".into());
    c.send(record.into());
    c.send_batch(vec!["a".into(), "b".into()]);
    c.flush(None).await.unwrap();
    let got = exp.records();
    assert_eq!(got.len(), 4);
    assert_eq!(got[0].timestamp, ts);
    assert!(got[0].observed_timestamp.is_some());
    assert_eq!(got[0].severity, Severity::Info);
    assert_eq!(got[0].severity_text, "INFO");
    assert_eq!(got[0].attributes["password"], "[REDACTED]");
    assert_eq!(got[0].resource["service.name"], "svc");
    assert_eq!(
        got[0].trace_id.as_deref(),
        Some("4bf92f3577b34da6a3ce929d0e0e4736")
    );
    assert_eq!(
        got[1].resource["service.name"], "own",
        "record resource wins"
    );
    assert_eq!(got[2].body, "a");
    assert_eq!(c.stats().sent, 4);
    assert_eq!(c.processor().stats().sent, 4);
    c.close().await.unwrap();
    c.close().await.unwrap();
    assert_eq!(exp.shutdown_calls(), 1);
}

#[tokio::test]
async fn redaction_can_be_replaced_or_disabled() {
    let exp = MemoryLogExporter::new();
    let c = BatchingLogClient::builder(Arc::new(exp.clone()))
        .redaction(None)
        .resource(attrs! { "host.name" => "h" })
        .batch_options(BatchOptions::default().max_batch_size(1))
        .build()
        .unwrap();
    c.send(LogInput::new("x").attribute("token", "t").into());
    c.flush(None).await.unwrap();
    assert_eq!(exp.records()[0].attributes["token"], "t");
    assert_eq!(exp.records()[0].resource["host.name"], "h");

    let exp = MemoryLogExporter::new();
    let c = BatchingLogClient::builder(Arc::new(exp.clone()))
        .redaction(Some(RedactionProcessor::new(["user"], vec![])))
        .build()
        .unwrap();
    let prepared = c.prepare(LogInput::new("x").attribute("user", "ada").into());
    assert_eq!(prepared.attributes["user"], "[REDACTED]");

    let c = BatchingLogClient::new(Arc::new(MemoryLogExporter::new())).unwrap();
    assert_eq!(c.stats().queued, 0);
}

#[tokio::test]
async fn send_async_waits_under_block_policy() {
    let exp = MemoryLogExporter::new();
    let c = BatchingLogClient::builder(Arc::new(exp.clone()))
        .batch_options(
            BatchOptions::default()
                .max_queue_size(1)
                .max_batch_size(1)
                .drop_policy(DropPolicy::Block),
        )
        .build()
        .unwrap();
    for i in 0..5 {
        assert!(c.send_async(format!("m{i}").into()).await);
    }
    c.close().await.unwrap();
    assert_eq!(exp.len(), 5);
}

#[tokio::test]
async fn logger_levels_children_and_names() {
    let exp = MemoryLogExporter::new();
    let c = client(&exp);
    let log = c.logger(Some("http"), attrs! { "base" => 1, "over" => "base" });
    assert_eq!(log.min_severity(), Severity::Debug);
    assert!(format!("{log:?}").contains("http"));
    log.trace("dropped", Attributes::new());
    log.debug("d", Attributes::new());
    log.info("i", attrs! { "over" => "call" });
    log.warn("w", Attributes::new());
    log.error("e", Attributes::new());
    log.fatal("f", Attributes::new());
    let child = log
        .child(attrs! { "child" => true })
        .with_min_severity(Severity::Error);
    assert!(!child.enabled(Severity::Warn));
    assert!(child.enabled(Severity::Fatal));
    assert_eq!(child.attributes()["base"], 1);
    child.warn("dropped", Attributes::new());
    child.error("ce", Attributes::new());
    let anon = c.logger(None, Attributes::new());
    anon.info("anon", Attributes::new());
    c.flush(None).await.unwrap();
    let got = exp.records();
    let bodies: Vec<&str> = got.iter().map(|r| r.body.as_str()).collect();
    assert_eq!(bodies, ["d", "i", "w", "e", "f", "ce", "anon"]);
    assert_eq!(got[1].attributes["over"], "call");
    assert_eq!(got[1].attributes["logger.name"], "http");
    assert_eq!(got[3].severity, Severity::Error);
    assert_eq!(got[5].attributes["child"], true);
    assert!(!got[6].attributes.contains_key("logger.name"));

    // A free-standing logger defaults to Info.
    let plain = Logger::new(Arc::new(c.clone()), Attributes::new());
    plain.debug("no", Attributes::new());
    plain.log(Severity::Info, "yes", Attributes::new());
    c.flush(None).await.unwrap();
    assert_eq!(exp.records().last().unwrap().body, "yes");
}

#[tokio::test]
async fn active_span_context_is_attached() {
    let exp = MemoryLogExporter::new();
    let c = client(&exp);
    let sc = SpanContext::new(
        TraceId::from_hex("4bf92f3577b34da6a3ce929d0e0e4736").unwrap(),
        SpanId::from_hex("00f067aa0ba902b7").unwrap(),
        TraceFlags::SAMPLED,
        true,
        TraceState::default(),
    );
    {
        let _guard = Context::new().with_remote_span_context(sc).attach();
        c.logger(None, Attributes::new())
            .info("in span", Attributes::new());
        c.send(LogInput::new("explicit").trace("aa", "bb").into());
    }
    c.send("outside".into());
    c.flush(None).await.unwrap();
    let got = exp.records();
    assert_eq!(
        got[0].trace_id.as_deref(),
        Some("4bf92f3577b34da6a3ce929d0e0e4736")
    );
    assert_eq!(got[0].span_id.as_deref(), Some("00f067aa0ba902b7"));
    assert_eq!(got[0].trace_flags, Some(1));
    assert_eq!(got[1].trace_id.as_deref(), Some("aa"));
    assert_eq!(got[1].trace_flags, None);
    assert_eq!(got[2].trace_id, None);
}
